<?php

declare(strict_types=1);

namespace Architex\Platform\Communication;

use Architex\Platform\Audit\AuditService;
use Architex\Platform\Identity\Identifier;
use Architex\Platform\Project\ProjectPhase;
use DateTimeImmutable;
use PDO;
use Throwable;

final readonly class ProjectCommunicationService
{
    public function __construct(private PDO $pdo){}

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function createThread(string $organisationId,string $userId,string $role,array $input):array
    {
        $this->assertWriter($organisationId,$userId,$role);$projectId=$this->id($input['projectId']??null,'communication_project_required');$this->project($organisationId,$projectId);$title=$this->text($input['title']??null,220,'communication_title_required');$phase=$this->phase($input['phase']??null);$channel=$this->choice($input['channel']??null,['project_group','direct','finance_thread','procurement_thread','support_thread','agent_thread'],'communication_channel_invalid');$visibility=$this->choice($input['visibility']??null,['project_team','client_visible','internal_team','admin_only'],'communication_visibility_invalid');$participantIds=$input['participantUserIds']??[];if(!is_array($participantIds))throw new CommunicationException('communication_participants_invalid');$participantIds=array_values(array_unique(array_merge([$userId],array_map(fn(mixed $id):string=>$this->id($id,'communication_participants_invalid'),$participantIds))));foreach($participantIds as $participantId)$this->member($organisationId,$participantId,'communication_participant_not_found');$id=Identifier::generate();$this->pdo->beginTransaction();try{$this->pdo->prepare('INSERT INTO communication_threads(id,organisation_id,project_id,title,phase,channel,visibility,created_by) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:project_id),:title,:phase,:channel,:visibility,UNHEX(:created_by))')->execute(['id'=>$id,'organisation_id'=>$organisationId,'project_id'=>$projectId,'title'=>$title,'phase'=>$phase,'channel'=>$channel,'visibility'=>$visibility,'created_by'=>$userId]);$insert=$this->pdo->prepare('INSERT INTO communication_thread_participants(id,thread_id,user_id,added_by) VALUES(UNHEX(:id),UNHEX(:thread_id),UNHEX(:user_id),UNHEX(:added_by))');foreach($participantIds as $participantId)$insert->execute(['id'=>Identifier::generate(),'thread_id'=>$id,'user_id'=>$participantId,'added_by'=>$userId]);(new AuditService($this->pdo))->append($organisationId,$userId,'communication.thread_created','communication_thread',$id,['projectId'=>$projectId,'phase'=>$phase,'channel'=>$channel,'visibility'=>$visibility,'participantCount'=>count($participantIds)]);$this->pdo->commit();return$this->getThread($organisationId,$userId,$id);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}
    }

    /** @return array<string,mixed> */
    public function getThread(string $organisationId,string $userId,string $threadId):array{$this->member($organisationId,$userId,'communication_thread_not_found');$s=$this->pdo->prepare('SELECT LOWER(HEX(t.id)) id,LOWER(HEX(t.project_id)) projectId,t.title,t.phase,t.channel,t.visibility,DATE_FORMAT(t.created_at,\'%Y-%m-%dT%H:%i:%s.%fZ\') createdAt FROM communication_threads t JOIN communication_thread_participants p ON p.thread_id=t.id AND p.user_id=UNHEX(:user_id) WHERE t.id=UNHEX(:id) AND t.organisation_id=UNHEX(:organisation_id)');$s->execute(['user_id'=>$userId,'id'=>$threadId,'organisation_id'=>$organisationId]);$row=$s->fetch();if(!is_array($row))throw new CommunicationException('communication_thread_not_found');$p=$this->pdo->prepare('SELECT LOWER(HEX(p.user_id)) userId,u.email,m.role FROM communication_thread_participants p JOIN users u ON u.id=p.user_id JOIN communication_threads t ON t.id=p.thread_id JOIN organisation_memberships m ON m.organisation_id=t.organisation_id AND m.user_id=p.user_id AND m.status=\'active\' WHERE p.thread_id=UNHEX(:id) ORDER BY u.email');$p->execute(['id'=>$threadId]);$row['participants']=$p->fetchAll();return$row;}

    /** @return list<array<string,mixed>> */
    public function listThreads(string $organisationId,string $userId,?string $projectId=null):array{$this->member($organisationId,$userId,'communication_permission_denied');$sql='SELECT LOWER(HEX(t.id)) id FROM communication_threads t JOIN communication_thread_participants p ON p.thread_id=t.id AND p.user_id=UNHEX(:user_id) WHERE t.organisation_id=UNHEX(:organisation_id)'.($projectId===null?'':' AND t.project_id=UNHEX(:project_id)').' ORDER BY t.created_at DESC,t.id';$params=['user_id'=>$userId,'organisation_id'=>$organisationId];if($projectId!==null){$projectId=$this->id($projectId,'communication_project_invalid');$params['project_id']=$projectId;}$s=$this->pdo->prepare($sql);$s->execute($params);return array_map(fn(string $id):array=>$this->getThread($organisationId,$userId,$id),$s->fetchAll(PDO::FETCH_COLUMN));}

    /** @return array<string,mixed> */
    public function phaseAssistant(string $organisationId,string $userId,string $projectId,string $phase):array{$this->member($organisationId,$userId,'communication_permission_denied');$this->project($organisationId,$projectId);$phase=$this->phase($phase);$config=self::phaseConfig()[$phase];$s=$this->pdo->prepare("SELECT SUM(status IN ('open','in_progress')) openActions,SUM(status IN ('open','in_progress') AND due_on<UTC_DATE()) overdueItems,SUM(conversion_type='approval' AND status IN ('open','in_progress')) pendingApprovals FROM communication_actions WHERE organisation_id=UNHEX(:organisation_id) AND project_id=UNHEX(:project_id)");$s->execute(['organisation_id'=>$organisationId,'project_id'=>$projectId]);$pulse=$s->fetch()?:[];return['heading'=>'Suggested prompts','description'=>'Phase-aware prompts based on the selected project stage, latest messages, open actions and available project records.','phase'=>$phase,'captureTypes'=>$config['captures'],'suggestedPrompts'=>$config['prompts'],'nextActions'=>$config['next'],'fileFocus'=>$config['files'],'projectPulse'=>['openActions'=>(int)($pulse['openActions']??0),'overdueItems'=>(int)($pulse['overdueItems']??0),'pendingApprovals'=>(int)($pulse['pendingApprovals']??0)]];}

    /** @return array<string,mixed> */
    public function markRead(string $organisationId,string $userId,string $threadId,string $messageId):array{$this->getThread($organisationId,$userId,$threadId);$message=$this->message($organisationId,$userId,$messageId,false);if($message['threadId']!==$threadId)throw new CommunicationException('communication_message_not_found');$this->pdo->prepare('INSERT INTO communication_read_cursors(thread_id,user_id,last_read_message_id) VALUES(UNHEX(:thread_id),UNHEX(:user_id),UNHEX(:message_id)) ON DUPLICATE KEY UPDATE last_read_message_id=VALUES(last_read_message_id),read_at=UTC_TIMESTAMP(6)')->execute(['thread_id'=>$threadId,'user_id'=>$userId,'message_id'=>$messageId]);return['threadId'=>$threadId,'lastReadMessageId'=>$messageId];}

    /** @return list<array<string,mixed>> */
    public function listActions(string $organisationId,string $userId,string $projectId):array{$this->member($organisationId,$userId,'communication_permission_denied');$this->project($organisationId,$projectId);$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id FROM communication_actions WHERE organisation_id=UNHEX(:organisation_id) AND project_id=UNHEX(:project_id) ORDER BY status,due_on,created_at DESC');$s->execute(['organisation_id'=>$organisationId,'project_id'=>$projectId]);return array_map(fn(string$id):array=>$this->action($organisationId,$id),$s->fetchAll(PDO::FETCH_COLUMN));}

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function draftContextualMessage(string $organisationId,string $userId,string $role,string $threadId,array $input):array
    {
        $this->assertWriter($organisationId,$userId,$role);$thread=$this->getThread($organisationId,$userId,$threadId);$body=$this->text($input['body']??null,12000,'communication_body_required');$phase=$this->phase($input['phase']??$thread['phase']);$captureType=$this->nullableText($input['captureType']??null,80);$kind=$this->choice($input['messageKind']??'text',['text','photo','document','voice_note','system'],'communication_kind_invalid');$context=$this->context($input['context']??null,$thread);$context['phaseId']=$phase;$linkedFiles=[];foreach($context['linkedFileIds'] as $linkedFile){$linkedFile=$this->id($linkedFile,'communication_context_file_not_found');$this->file($organisationId,(string)$thread['projectId'],$linkedFile,'communication_context_file_not_found');$linkedFiles[]=$linkedFile;}$context['linkedFileIds']=array_values(array_unique($linkedFiles));$attachment=$input['attachmentFileId']??null;if($attachment!==null){$attachment=$this->id($attachment,'communication_attachment_invalid');$this->file($organisationId,(string)$thread['projectId'],$attachment);}$reply=$input['replyToMessageId']??null;if($reply!==null){$reply=$this->id($reply,'communication_reply_invalid');$replyMessage=$this->message($organisationId,$userId,$reply,true);if($replyMessage['threadId']!==$threadId)throw new CommunicationException('communication_reply_not_found');}$location=$input['location']??null;if($location!==null&&!is_array($location))throw new CommunicationException('communication_location_invalid');$id=Identifier::generate();$this->pdo->beginTransaction();try{$this->pdo->prepare('INSERT INTO project_messages(id,thread_id,organisation_id,project_id,sender_user_id,reply_to_message_id,attachment_file_id,message_kind,body,phase,capture_type,visibility,context,transcribed_text,location) VALUES(UNHEX(:id),UNHEX(:thread_id),UNHEX(:organisation_id),UNHEX(:project_id),UNHEX(:sender),UNHEX(:reply),UNHEX(:attachment),:kind,:body,:phase,:capture_type,:visibility,:context,:transcribed,:location)')->execute(['id'=>$id,'thread_id'=>$threadId,'organisation_id'=>$organisationId,'project_id'=>$thread['projectId'],'sender'=>$userId,'reply'=>$reply,'attachment'=>$attachment,'kind'=>$kind,'body'=>$body,'phase'=>$phase,'capture_type'=>$captureType,'visibility'=>$thread['visibility'],'context'=>$this->json($context),'transcribed'=>$this->nullableText($input['transcribedText']??null,12000),'location'=>$location===null?null:$this->json($location)]);(new AuditService($this->pdo))->append($organisationId,$userId,'communication.contextual_draft_created','project_message',$id,['threadId'=>$threadId,'projectId'=>$thread['projectId'],'phase'=>$phase,'captureType'=>$captureType,'sourceObjectType'=>$context['sourceObjectType'],'sourceObjectId'=>$context['sourceObjectId']]);$this->pdo->commit();$message=$this->message($organisationId,$userId,$id,true);$message['requiresUserApproval']=true;return$message;}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}
    }

    /** @return array<string,mixed> */
    public function sendDraft(string $organisationId,string $userId,string $role,string $messageId,bool $humanConfirmed):array
    {
        $this->assertWriter($organisationId,$userId,$role);if(!$humanConfirmed)throw new CommunicationException('communication_send_confirmation_required');$message=$this->message($organisationId,$userId,$messageId,true);if($message['senderUserId']!==$userId)throw new CommunicationException('communication_message_not_found');if($message['status']!=='draft')throw new CommunicationException('communication_message_not_draft');$this->pdo->beginTransaction();try{$update=$this->pdo->prepare("UPDATE project_messages SET status='sent',sent_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND status='draft'");$update->execute(['id'=>$messageId]);if($update->rowCount()!==1)throw new CommunicationException('communication_message_not_draft');(new AuditService($this->pdo))->append($organisationId,$userId,'communication.message_sent','project_message',$messageId,['threadId'=>$message['threadId'],'projectId'=>$message['projectId'],'persistencePolicy'=>$message['context']['persistencePolicy'],'auditPolicy'=>$message['context']['auditPolicy']]);$this->pdo->commit();return$this->message($organisationId,$userId,$messageId,false);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}
    }

    /** @param array<string,mixed> $filters @return list<array<string,mixed>> */
    public function listMessages(string $organisationId,string $userId,string $role,string $threadId,array $filters):array
    {
        $this->member($organisationId,$userId,'communication_thread_not_found');$this->getThread($organisationId,$userId,$threadId);$sql="SELECT LOWER(HEX(id)) id FROM project_messages WHERE thread_id=UNHEX(:thread_id) AND organisation_id=UNHEX(:organisation_id) AND status='sent'";$params=['thread_id'=>$threadId,'organisation_id'=>$organisationId];foreach(['phase'=>'phase','captureType'=>'capture_type','messageKind'=>'message_kind'] as $key=>$column)if(is_string($filters[$key]??null)&&$filters[$key]!==''){$sql.=" AND $column=:$key";$params[$key]=$filters[$key];}if(is_string($filters['search']??null)&&trim($filters['search'])!==''){$sql.=' AND body LIKE :search';$params['search']='%'.trim($filters['search']).'%';}$sql.=' ORDER BY created_at,id LIMIT 200';$s=$this->pdo->prepare($sql);$s->execute($params);return array_map(fn(string $id):array=>$this->message($organisationId,$userId,$id,false),$s->fetchAll(PDO::FETCH_COLUMN));
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function convertMessage(string $organisationId,string $userId,string $role,string $messageId,array $input):array
    {
        $this->assertWriter($organisationId,$userId,$role);if(($input['humanConfirmed']??false)!==true)throw new CommunicationException('communication_conversion_confirmation_required');$message=$this->message($organisationId,$userId,$messageId,false);$type=$this->choice($input['conversionType']??null,['action','rfi','site_instruction','approval'],'communication_conversion_type_invalid');$title=$this->text($input['title']??null,220,'communication_conversion_title_required');$assigned=$input['assignedUserId']??null;$assignedRole='member';if($assigned!==null){$assigned=$this->id($assigned,'communication_assignee_invalid');$assignedRole=$this->member($organisationId,$assigned,'communication_assignee_not_found');}$due=$input['dueOn']??null;if($due!==null&&(!is_string($due)||DateTimeImmutable::createFromFormat('!Y-m-d',$due)?->format('Y-m-d')!==$due))throw new CommunicationException('communication_due_date_invalid');$id=Identifier::generate();$payload=['messageId'=>$messageId,'threadId'=>$message['threadId'],'context'=>$message['context'],'sourceBody'=>$message['body'],'humanConfirmed'=>true];$this->pdo->beginTransaction();try{$this->pdo->prepare('INSERT INTO communication_actions(id,organisation_id,project_id,source_message_id,conversion_type,title,assigned_user_id,due_on,approved_by,payload) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:project_id),UNHEX(:message_id),:type,:title,UNHEX(:assigned),:due,UNHEX(:approved_by),:payload)')->execute(['id'=>$id,'organisation_id'=>$organisationId,'project_id'=>$message['projectId'],'message_id'=>$messageId,'type'=>$type,'title'=>$title,'assigned'=>$assigned,'due'=>$due,'approved_by'=>$userId,'payload'=>$this->json($payload)]);$this->pdo->prepare("UPDATE project_messages SET structured_status='converted' WHERE id=UNHEX(:id)")->execute(['id'=>$messageId]);$this->pdo->prepare('INSERT INTO inbox_items(id,organisation_id,project_id,assigned_user_id,assigned_role,event_type,title,detail,priority,payload) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:project_id),UNHEX(:assigned_user_id),:assigned_role,:event_type,:title,:detail,:priority,:payload)')->execute(['id'=>Identifier::generate(),'organisation_id'=>$organisationId,'project_id'=>$message['projectId'],'assigned_user_id'=>$assigned,'assigned_role'=>$assigned===null?$role:$assignedRole,'event_type'=>'communication.'.$type,'title'=>$title,'detail'=>'Human-approved conversion from project communication.','priority'=>$type==='site_instruction'?'high':'medium','payload'=>$this->json($payload+['actionId'=>$id])]);(new AuditService($this->pdo))->append($organisationId,$userId,'communication.message_converted','project_message',$messageId,['actionId'=>$id,'conversionType'=>$type,'assignedUserId'=>$assigned,'dueOn'=>$due]);$this->pdo->commit();return$this->action($organisationId,$id);}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();if($e instanceof \PDOException&&$e->getCode()==='23000')throw new CommunicationException('communication_conversion_exists');throw$e;}
    }

    /** @return array<string,mixed> */
    private function message(string $organisationId,string $userId,string $id,bool $includeDraft):array{$s=$this->pdo->prepare('SELECT LOWER(HEX(m.id)) id,LOWER(HEX(m.thread_id)) threadId,LOWER(HEX(m.project_id)) projectId,LOWER(HEX(m.sender_user_id)) senderUserId,u.email senderEmail,LOWER(HEX(m.reply_to_message_id)) replyToMessageId,LOWER(HEX(m.attachment_file_id)) attachmentFileId,m.message_kind messageKind,m.body,m.phase,m.capture_type captureType,m.visibility,m.structured_status structuredStatus,m.status,m.context,m.transcribed_text transcribedText,m.location,DATE_FORMAT(m.sent_at,\'%Y-%m-%dT%H:%i:%s.%fZ\') sentAt,DATE_FORMAT(m.created_at,\'%Y-%m-%dT%H:%i:%s.%fZ\') createdAt FROM project_messages m JOIN users u ON u.id=m.sender_user_id JOIN communication_thread_participants p ON p.thread_id=m.thread_id AND p.user_id=UNHEX(:user_id) WHERE m.id=UNHEX(:id) AND m.organisation_id=UNHEX(:organisation_id)'.($includeDraft?'':" AND m.status='sent'"));$s->execute(['user_id'=>$userId,'id'=>$id,'organisation_id'=>$organisationId]);$row=$s->fetch();if(!is_array($row))throw new CommunicationException('communication_message_not_found');$row['context']=json_decode((string)$row['context'],true,64,JSON_THROW_ON_ERROR);$row['location']=$row['location']===null?null:json_decode((string)$row['location'],true,64,JSON_THROW_ON_ERROR);return$row;}
    /** @return array<string,mixed> */
    private function action(string $organisationId,string $id):array{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) projectId,LOWER(HEX(source_message_id)) sourceMessageId,conversion_type conversionType,title,LOWER(HEX(assigned_user_id)) assignedUserId,due_on dueOn,status,LOWER(HEX(approved_by)) approvedBy,payload FROM communication_actions WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id)');$s->execute(['id'=>$id,'organisation_id'=>$organisationId]);$row=$s->fetch();if(!is_array($row))throw new CommunicationException('communication_action_not_found');$row['payload']=json_decode((string)$row['payload'],true,64,JSON_THROW_ON_ERROR);return$row;}
    /** @param array<string,mixed> $thread @return array<string,mixed> */
    private function context(mixed $value,array $thread):array{if(!is_array($value))throw new CommunicationException('communication_context_required');$source=$this->choice($value['sourceObjectType']??null,['project_dashboard','snag_item','rfi','site_instruction','variation','payment_certificate','drawdown_request','quote_comparison','bom_item','drawing_compliance_issue','council_submission_item','cpd_assessment','cpd_certificate','cpd_manual_submission','cpd_course','marketplace_quote_request','document_review_item','agent_inbox_action_card'],'communication_context_source_invalid');$policy=$this->choice($value['persistencePolicy']??null,['conversation_only','project_record','source_object_record','audit_required','agent_action_required'],'communication_persistence_policy_invalid');$audit=$this->choice($value['auditPolicy']??'none',['none','record_summary','approval_required'],'communication_audit_policy_invalid');$files=$value['linkedFileIds']??[];if(!is_array($files))throw new CommunicationException('communication_context_files_invalid');return['contextId'=>$source.':'.$this->text($value['sourceObjectId']??null,180,'communication_context_source_id_required'),'projectId'=>$thread['projectId'],'phaseId'=>$thread['phase'],'moduleKey'=>$this->text($value['moduleKey']??null,80,'communication_context_module_required'),'sourceObjectType'=>$source,'sourceObjectId'=>$this->text($value['sourceObjectId']??null,180,'communication_context_source_id_required'),'title'=>$this->text($value['title']??null,220,'communication_context_title_required'),'status'=>$this->nullableText($value['status']??null,80),'summary'=>$this->text($value['summary']??null,1000,'communication_context_summary_required'),'suggestedRecipients'=>$value['suggestedRecipients']??[],'suggestedChannel'=>$thread['channel'],'linkedFileIds'=>$files,'persistencePolicy'=>$policy,'auditPolicy'=>$audit];}
    private function project(string $organisationId,string $projectId):void{$s=$this->pdo->prepare('SELECT 1 FROM projects WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id)');$s->execute(['id'=>$projectId,'organisation_id'=>$organisationId]);if($s->fetchColumn()===false)throw new CommunicationException('communication_project_not_found');}
    private function file(string $organisationId,string $projectId,string $fileId,string $reason='communication_attachment_not_found'):void{$s=$this->pdo->prepare("SELECT 1 FROM stored_files WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id) AND project_id=UNHEX(:project_id) AND status='active'");$s->execute(['id'=>$fileId,'organisation_id'=>$organisationId,'project_id'=>$projectId]);if($s->fetchColumn()===false)throw new CommunicationException($reason);}
    private function assertWriter(string $organisationId,string $userId,string $role):void{if(!in_array($role,['owner','admin','member'],true))throw new CommunicationException('communication_permission_denied');$this->member($organisationId,$userId,'communication_permission_denied');}
    private function member(string $organisationId,string $userId,string $reason):string{$s=$this->pdo->prepare("SELECT role FROM organisation_memberships WHERE organisation_id=UNHEX(:organisation_id) AND user_id=UNHEX(:user_id) AND status='active'");$s->execute(['organisation_id'=>$organisationId,'user_id'=>$userId]);$role=$s->fetchColumn();if(!is_string($role))throw new CommunicationException($reason);return$role;}
    private function phase(mixed $value):string{$phase=$this->text($value,40,'communication_phase_required');if(ProjectPhase::tryFrom($phase)===null)throw new CommunicationException('communication_phase_invalid');return$phase;}
    /** @return array<string,array{captures:list<string>,prompts:list<string>,next:list<string>,files:list<string>}> */
    private static function phaseConfig():array{return[
        'onboarding'=>['captures'=>['new_enquiry','property_address','client_requirement','budget_range','timeline_target','site_photo'],'prompts'=>['Summarise the client brief from this thread.','List missing intake information.'],'next'=>['Confirm project intent','Collect property information'],'files'=>['Title deed','Existing plans','Site photos']],
        'feasibility'=>['captures'=>['brief_requirement','feasibility_constraint','planning_flag','existing_condition','concept_option','budget_risk'],'prompts'=>['List feasibility risks before proceeding.','Summarise unresolved client preferences.'],'next'=>['Review constraints','Confirm feasibility route'],'files'=>['Survey','Zoning information','Concept evidence']],
        'appointment'=>['captures'=>['fee_item','appointment_document','scope_clarification','team_invite','contract_query'],'prompts'=>['List outstanding appointment gates.','Summarise scope clarifications.'],'next'=>['Confirm appointment','Complete project team'],'files'=>['Accepted proposal','Appointment letter','Team credentials']],
        'concept_design'=>['captures'=>['design_decision','client_comment','concept_option','approval_needed'],'prompts'=>['What concept decisions remain unresolved?','Summarise client approvals needed.'],'next'=>['Review options','Record client direction'],'files'=>['Concept drawings','Brief revisions','Approval evidence']],
        'design_development'=>['captures'=>['design_decision','consultant_query','drawing_markup','coordination_item','client_comment','information_required'],'prompts'=>['What design decisions are still unresolved?','Extract consultant queries and owners.'],'next'=>['Resolve coordination items','Confirm drawing changes'],'files'=>['Coordinated drawings','Consultant markups','Design decisions']],
        'municipal_submission'=>['captures'=>['sans_nbr_risk','municipal_checklist_item','council_comment','missing_document','fire_access_energy_item','resubmission_item'],'prompts'=>['What municipal submission items are missing?','Summarise unresolved council comments.'],'next'=>['Close readiness blockers','Confirm submission evidence'],'files'=>['Submission drawings','Forms and signatures','Council correspondence']],
        'tender_procurement'=>['captures'=>['tender_clarification','contractor_query','addendum','pricing_exclusion','alternative_product','comparison_note'],'prompts'=>['Extract all contractor clarifications.','List tender decisions needing approval.'],'next'=>['Issue approved clarification','Update tender record'],'files'=>['Tender package','Addenda','Bid comparisons']],
        'construction_execution'=>['captures'=>['site_photo','progress_photo','rfi','site_instruction','variation','snag_defect','safety_item','delivery_material','inspection_note','time_cost_impact'],'prompts'=>['What site issues could affect time or cost?','List open RFIs and instructions.'],'next'=>['Assign site actions','Review contractual impact'],'files'=>['Site photos','RFIs','Instructions','Inspection records']],
        'closeout'=>['captures'=>['snag_closeout','completion_item','certificate','warranty','as_built_drawing','occupation_document','maintenance_note','final_handover_item'],'prompts'=>['List documents still required for handover.','Summarise open closeout actions.'],'next'=>['Close outstanding snags','Assemble handover record'],'files'=>['As-builts','Certificates','Warranties','Handover documents']],
    ];}
    private function id(mixed $value,string $reason):string{if(!is_string($value)||preg_match('/\A[a-f0-9]{32}\z/i',$value)!==1)throw new CommunicationException($reason);return strtolower($value);}
    private function text(mixed $value,int $max,string $reason):string{$value=is_string($value)?trim($value):'';if($value===''||mb_strlen($value)>$max)throw new CommunicationException($reason);return$value;}
    private function nullableText(mixed $value,int $max):?string{if($value===null||$value==='')return null;if(!is_string($value)||mb_strlen(trim($value))>$max)throw new CommunicationException('communication_text_invalid');return trim($value);}
    /** @param list<string> $allowed */private function choice(mixed $value,array $allowed,string $reason):string{if(!is_string($value)||!in_array($value,$allowed,true))throw new CommunicationException($reason);return$value;}
    /** @param array<string,mixed>|list<mixed> $value */private function json(array $value):string{return json_encode($value,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
}
